		templ_7745c5c3_Var7 := templ.GetChildren(ctx)
		if templ_7745c5c3_Var7 == nil {
			templ_7745c5c3_Var7 = templ.NopComponent
		}
		ctx = templ.ClearChildren(ctx)
		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 7, "<section id=\"tafs\"><h2>3A. tafs</h2><p>ใน tafs คุณมอบงาน (เช่น การคืนเงิน การชำระบิล หรือข้อพิพาทเกี่ยวกับบัตร) ให้ taf: เอเจนต์ AI ที่ทำงานตามกำหนดเวลาด้วยเครื่องมือที่คุณเชื่อมต่อ ภายใน KIFF Card ที่คุณออกให้ taf แต่ละตัวรันบนรันไทม์เอเจนต์ของเรา และ Anthropic เป็นผู้จัดหาโมเดล AI ที่ taf ใช้ คุณตอบการเรียกที่ถูกพักไว้ของ taf ในแอป tafs</p><p><strong>การเชื่อมต่อเครื่องมือของคุณ</strong> Setup เอเจนต์ AI ใน tafs ที่ทำงานเหมือน taf ช่วยคุณเชื่อมต่อเครื่องมือและตั้งค่า taf สำหรับงาน Setup ไม่เชื่อมต่อสิ่งใดด้วยตัวเอง คุณลงชื่อเข้าใช้ที่ผู้ให้บริการของเครื่องมือนั้นเอง (เช่น Stripe) และอนุมัติบนอุปกรณ์ของคุณทุกการเชื่อมต่อ เครื่องมือที่ taf ใช้ได้ และ Card ของ taf โทเค็นจากการลงชื่อเข้าใช้นั้นถูกเก็บโดย planque บริการเชื่อมต่อของเรา โทเค็นถูกเข้ารหัส ใช้เฉพาะเพื่อทำการเรียกที่ KIFF ตัดสินใจแล้ว และไม่เคยมอบให้ taf การตัดการเชื่อมต่อเครื่องมือเพิกถอนโทเค็นที่ผู้ให้บริการและลบโทเค็น</p><p><strong>Card ของคุณคือคำสั่งของคุณ</strong> taf เข้าถึงเครื่องมือของคุณผ่าน KIFF เท่านั้น ซึ่งตรวจสอบทุกการเรียกเทียบกับ Card ของ taf ก่อนส่ง การเรียกที่อยู่ภายใน Card ที่คุณออกให้ถูกทำตามคำสั่งของคุณ การเรียกที่อยู่นอก Card จะถูกพักไว้หรือถูกปฏิเสธ ตามที่ Card ระบุ การเรียกที่ถูกพักไว้จะทำได้ก็ต่อเมื่อบุคคลที่บัญชีของคุณอนุญาตให้ตอบการเรียกที่ถูกพักไว้เป็นผู้อนุมัติ ในแอป tafs คำตอบมีลายเซ็นจากอุปกรณ์ของบุคคลนั้นที่ KIFF ตรวจสอบ และใบเสร็จเก็บหลักฐานนั้น บัญชีของคุณยังตอบได้ใน KIFF เอง (แดชบอร์ด เครื่องมือบรรทัดคำสั่ง หรือผู้อนุมัติที่คุณอนุญาตที่นั่น) ใบเสร็จจึงบันทึกว่าใครตอบและตอบอย่างไร</p><p><strong>สิ่งที่ยังเป็นของคุณ</strong> คุณเลือกงานและ Card ของ taf แต่ละตัว ตอบการเรียกที่ถูกพักไว้ และดูแลให้คุณมีสิทธิ์ใช้เครื่องมือและบัญชีที่คุณเชื่อมต่อ รายงาน ข้อความ และบันทึกความจำของ taf เขียนโดยโมเดล AI และอาจผิดพลาดได้ ตรวจสอบสิ่งสำคัญก่อนพึ่งพา</p><p><strong>การหยุด taf</strong> คุณสามารถหยุด taf หนึ่งตัวหรือทั้งหมด พัก taf เพิกถอน Card ใด ๆ ของ taf หรือลบ taf ตั้งแต่ขณะที่คุณหยุด taf หรือเพิกถอน Card KIFF ไม่อนุญาตการเรียกใหม่ภายใต้สิ่งนั้น แอป tafs แสดง taf ว่าถูกหยุดก็ต่อเมื่อ KIFF และ planque ยืนยันการหยุดทั้งคู่แล้ว ตั้งแต่นั้น planque ไม่ส่งการเรียกใดของ taf รวมถึงการเรียกที่ KIFF เพิ่งอนุญาตก่อนหน้านั้น คำขอที่ส่งไปยังผู้ให้บริการของเครื่องมือแล้วอาจยังดำเนินการเสร็จ: เราหยุดการเรียกใหม่ และไม่สามารถย้อนสิ่งที่ผู้ให้บริการทำไปแล้ว เครื่องมือที่ตรวจสอบใบอนุญาตของ KIFF เองโดยไม่ผ่าน planque อาจยังรับใบอนุญาตที่ KIFF เพิ่งออกก่อนหน้า ไม่เกิน 90 วินาที การกลับมาทำงานของ taf ที่ถูกหยุดต้องได้รับการอนุมัติของคุณบนอุปกรณ์ของคุณ และสิ่งที่ถูกพักหรือเข้าคิวก่อนการหยุดจะไม่ทำงานหลังจากนั้น</p><p><strong>การลบ taf</strong> หยุดกำหนดเวลาของ taf และลบการทำงาน แชต ความจำ และคีย์ที่ taf ใช้ แม้ก่อนหน้านั้น สิ่งที่เครื่องมือของคุณส่งคืนให้ taf ถูกเก็บจนกว่าการทำงานของ taf จบเท่านั้น (สิ่งที่แชตเพียงอ่าน เข้ารหัส สำหรับข้อความถัดไป: ใช้ไม่เกินสี่ชั่วโมง แล้วลบ) และการทำงานและแชตของ taf เก็บ 30 วัน KIFF เก็บใบเสร็จของสิ่งที่ taf ทำ</p><p><strong>กฎหมาย AI ของสหภาพยุโรป</strong> สำหรับ tafs Kiff Agents OÜ เป็นผู้ให้บริการระบบ AI และคุณเป็นผู้นำไปใช้งาน (deployer) เราดูแลให้สิ่งที่ taf เขียนถึงบุคคลนอกบริษัทของคุณระบุว่าเอเจนต์ AI เป็นผู้เขียน คุณใช้ tafs เฉพาะกับงานที่ tafs เสนอ และไม่ใช้กับการใช้งานใด ๆ ที่กฎหมาย AI ห้ามหรือจัดว่ามีความเสี่ยงสูง เช่น การตัดสินใจเกี่ยวกับการจ้างงาน สินเชื่อ หรือการเข้าถึงบริการที่จำเป็นของบุคคล คุณรักษาการอนุมัติจากมนุษย์ที่ Card ของคุณกำหนด และดูแลให้ผู้ที่ใช้ tafs แทนคุณเข้าใจว่า tafs ทำอะไรและขีดจำกัดของ tafs</p><p><strong>ค่าใช้จ่าย</strong> tafs เป็นส่วนหนึ่งของแผน KIFF ของคุณ (§8): การทำงานแต่ละรอบของ taf ใช้เครดิตสำหรับ AI ที่ใช้ Coach และการตั้งค่า taf รวมอยู่ภายใต้การใช้งานอย่างเป็นธรรมของ Coach</p></section>")
		if templ_7745c5c3_Err != nil {
			return templ_7745c5c3_Err
		}
		return nil
